SELECT 
FROM context_compaction_task
WHERE user_id = #{userId}
  AND session_id = #{sessionId}
  AND (status IN ('pending', 'retrying') OR (status = 'processing' AND lease_until < CURRENT_TIMESTAMP(3)))
  AND deleted = 0


        AND (tenant_id IS NULL OR tenant_id = '')


        AND tenant_id = #{tenantId}


ORDER BY id ASC
LIMIT 20

