UPDATE context_compaction_task
SET status = 'stale', lease_owner = NULL, lease_until = NULL, error_message = #{reason}
WHERE user_id = #{userId} AND session_id = #{sessionId}
  AND status IN ('pending', 'processing', 'retrying', 'succeeded')
  AND (run_id = #{runId} OR (from_sequence <= #{maxSequence} AND to_sequence >= #{minSequence}))
  AND deleted = 0
AND (tenant_id IS NULL OR tenant_id = '')AND tenant_id = #{tenantId}
